class Osoba {
  constructor(imie, wiek) {
    this.imie = imie; // pole instancji - ustawiane przy tworzeniu
    this.wiek = wiek;
  }

  przywitajSie() {
    return `Czesc, jestem ${this.imie} i mam ${this.wiek} lat.`;
  }

  urodziny() {
    this.wiek++;
    return this.wiek;
  }
}

const jan = new Osoba("Jan", 30);
const ewa = new Osoba("Ewa", 25);

console.log(jan.przywitajSie()); // "Czesc, jestem Jan i mam 30 lat."
console.log(ewa.przywitajSie()); // "Czesc, jestem Ewa i mam 25 lat."

jan.urodziny();
console.log(jan.wiek); // 31
console.log(ewa.wiek); // 25 - bez zmian, obiekty sa niezalezne

