class Film {
  constructor(tytul, rezyser) {
    this.tytul = tytul;
    this.rezyser = rezyser;
  }
  opis() {
    return `"${this.tytul}" rez. ${this.rezyser}`;
  }
}

const film = new Film("Incepcja", "Christopher Nolan");
console.log(film.opis()); // "Incepcja" rez. Christopher Nolan

class Rower {
  constructor(marka, przebieg = 0) {
    this.marka = marka;
    this.przebieg = przebieg;
  }
  jedz(km) {
    this.przebieg += km;
  }
}

const rower = new Rower("Trek");
rower.jedz(10);
rower.jedz(5);
console.log(rower.przebieg); // 15

