class Zamowienie {
  constructor(produkt, ilosc) {
    this.produkt = produkt;
    this.ilosc = ilosc;
  }
  wartosc(cenaJednostkowa) {
    return this.ilosc * cenaJednostkowa;
  }
}

const zamowienie = new Zamowienie("Klawiatura", 3);
console.log(zamowienie.wartosc(15)); // 45

class Ksiazka {
  constructor(tytul, liczbaStron) {
    this.tytul = tytul;
    this.liczbaStron = liczbaStron;
    this.przeczytanoStron = 0;
  }
  czytaj(strony) {
    this.przeczytanoStron = Math.min(this.przeczytanoStron + strony, this.liczbaStron);
  }
}

const ksiazka = new Ksiazka("Diuna", 250);
ksiazka.czytaj(100);
console.log(ksiazka.przeczytanoStron); // 100
ksiazka.czytaj(200);
console.log(ksiazka.przeczytanoStron); // 250 (nie 300)

class Termometr {
  constructor(temperatura) {
    this.temperatura = temperatura;
  }
  ogrzej(o) {
    this.temperatura += o;
  }
  ochlodz(o) {
    this.temperatura -= o;
  }
}

const termometr = new Termometr(20);
termometr.ogrzej(5);
termometr.ochlodz(3);
console.log(termometr.temperatura); // 22

class Walizka {
  constructor(pojemnoscKg) {
    this.pojemnoscKg = pojemnoscKg;
    this.zapakowanoKg = 0;
  }
  dodajBagaz(kg) {
    if (this.zapakowanoKg + kg <= this.pojemnoscKg) {
      this.zapakowanoKg += kg;
      return true;
    }
    return false;
  }
}

const walizka = new Walizka(20);
console.log(walizka.dodajBagaz(15)); // true
console.log(walizka.dodajBagaz(10)); // false - przekroczylby 20kg

